class Solution:
    def addEdges(self, n, edges):
        parent = list(range(n))
        par = [0] * n
        def find(x):
            if parent[x] == x:
                return x, 0
            r, p = find(parent[x])
            parent[x] = r
            par[x] ^= p
            return r, par[x]
        cnt = 0
        for u, v, w in edges:
            ru, pu = find(u)
            rv, pv = find(v)
            if ru == rv:
                if (w ^ pu ^ pv) == 0:
                    cnt += 1
            else:
                parent[ru] = rv
                par[ru] = pu ^ pv ^ w
                cnt += 1
        return cnt

