class Solution {
    vector<int> parent, par;
    pair<int,int> find(int x) {
        if (parent[x] == x) return {x, 0};
        auto [r, p] = find(parent[x]);
        parent[x] = r;
        par[x] ^= p;
        return {r, par[x]};
    }
public:
    int addEdges(int n, vector<vector<int>>& edges) {
        parent.resize(n); par.assign(n, 0);
        iota(parent.begin(), parent.end(), 0);
        int cnt = 0;
        for (auto& e : edges) {
            auto [ru, pu] = find(e[0]);
            auto [rv, pv] = find(e[1]);
            if (ru == rv) {
                if ((e[2] ^ pu ^ pv) == 0) cnt++;
            } else {
                parent[ru] = rv;
                par[ru] = pu ^ pv ^ e[2];
                cnt++;
            }
        }
        return cnt;
    }
};

