class Solution {
    int[] parent, par;
    int[] find(int x) {
        if (parent[x] == x) return new int[]{x, 0};
        int[] rp = find(parent[x]);
        parent[x] = rp[0];
        par[x] ^= rp[1];
        return new int[]{rp[0], par[x]};
    }
    public int addEdges(int n, int[][] edges) {
        parent = new int[n]; par = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;
        int cnt = 0;
        for (int[] e : edges) {
            int[] a = find(e[0]), b = find(e[1]);
            if (a[0] == b[0]) {
                if ((e[2] ^ a[1] ^ b[1]) == 0) cnt++;
            } else {
                parent[a[0]] = b[0];
                par[a[0]] = a[1] ^ b[1] ^ e[2];
                cnt++;
            }
        }
        return cnt;
    }
}

