var addEdges = function(n, edges) {
    const parent = [...Array(n).keys()], par = new Array(n).fill(0);
    function find(x) {
        if (parent[x] === x) return [x, 0];
        const [r, p] = find(parent[x]);
        parent[x] = r;
        par[x] ^= p;
        return [r, par[x]];
    }
    let cnt = 0;
    for (const [u, v, w] of edges) {
        const [ru, pu] = find(u), [rv, pv] = find(v);
        if (ru === rv) {
            if ((w ^ pu ^ pv) === 0) cnt++;
        } else {
            parent[ru] = rv;
            par[ru] = pu ^ pv ^ w;
            cnt++;
        }
    }
    return cnt;
};
